	def buildColorDict(bgColors):
		bgColorDict = {}
		for bgColor in bgColors:
			bgColorDict[bgColor] = system.kanoa.utilities.getContrastingColor(bgColor)

		return bgColorDict

	def buildLabel(mode, workOrder, productCode, itemDescription):
		if mode  != 'Production': return mode
		if (productCode or None) is None and (workOrder or None) is None:	return 'Production'
		if (workOrder or None) is not None or (productCode or None) is not None: mode = None
		labels = [mode, workOrder, productCode, itemDescription]
		return 	" ".join(v for v in labels if v not in (None, ""))
#		return productCode or ''

	def buildEvent(itemId, startDate, endDate, label, bgColor):	
		return {'itemId': itemId, 'eventId': len(scheduledEvents), 'startDate': startDate, 'endDate': endDate or system.date.now(), 'label':label, 'leadTime': 0, 'leadStyle': {}, 'percentDone': 0,'style': {"backgroundColor": bgColor,	"color": bgColorDict[bgColor]}}

	def buildItem(asset, label, eventType, itemId, index):
		if eventType == 'Schedule': 
			iconPath = "material/calendar_today"
			iconColor = ''
		elif eventType == 'Mode':
			modeInfo = system.kanoa.asset.getCurrentModeInfo(asset['assetPath'])
			iconPath = modeInfo['iconPath'] if modeInfo.has_key('iconPath') else ''
			iconColor = modeInfo['modeColor'] if modeInfo.has_key('modeColor') else ''

		elif eventType == 'State': 
			stateInfo = system.kanoa.asset.getCurrentStateInfo(asset['assetPath'])
			iconPath = stateInfo['iconPath'] if stateInfo.has_key('iconPath') else ''
			iconColor = stateInfo['modeColor'] if stateInfo.has_key('modeColor') else ''

		return {
				'id': itemId,
				'label': label,
				'iconConfig': {'path': iconPath, 'color': iconColor, 'style': {"minWidth": 24, "maxWidth": 24, "stroke": '--kcGray-100', "strokeWidth": 0.5}},
				'headerStyle': {"fontSize": "10px"},
				'rowStyle': {'backgroundColor': '--kcGray-10' if (index % 2 == 0) else '--kcGray-0', 'color': '--kcGray-100'},
				'data': {'eqPath': asset['assetPath'], 'eventType': eventType, 'assetId': asset['assetId']}
			}

#	system.perspective.print("getData() called")
	params = self.view.params.values
	assetPath = params['eqPath'] if params.has_key('eqPath') else None
	startDate = params['startDate']
	startDate = system.date.addDays(startDate, -1)
	endDate = params['endDate']

	if assetPath is None: return

	self.custom.info = {"showBar": True, "text": "Getting Info", "type": "INFO"}		

	assetData = system.kanoa.asset.getAssets({'assetPath': assetPath + '%', 'assetTypeIdList':params['assetTypes'], 'oeeEnabled': True, 'enabled': True})
	assets = system.kanoa.utilities.convertDatasetToJSON(assetData)

	itemId = 0
	theme = self.session.props.theme.split("-")[0].capitalize()
	items = []	

	sitePath = system.kanoa.utilities.convertDatasetRowToJSON(system.kanoa.asset.getParentAsset('site', assetPath),0)['assetPath'] if assetPath else ''

	#Now build schedule
	for index, asset in enumerate(assets):
		label = system.kanoa.utilities.formatPath(asset['assetPath'], {'drop':sitePath})
		if not label: label = asset['assetName']
		if params['eventTypes']['schedule']:
			if asset['assetTypeName'] != 'cell':
				itemId += 1 
				items.append(buildItem(asset, label + '\n Schedule', 'Schedule', itemId, index))
		if params['eventTypes']['mode']:
			itemId += 1
			if asset['assetTypeName'] != 'cell': label = 'Mode' if params['eventTypes']['schedule'] else label + '\n Mode'
			else: label = label + '\n Mode'
			items.append(buildItem(asset, label, 'Mode', itemId, index))
		if params['eventTypes']['state']:
			itemId += 1
			label = 'State' if params['eventTypes']['schedule'] or params['eventTypes']['mode'] else label + '\n State'
			items.append(buildItem(asset, label, 'State', itemId, index))

	self.view.custom.items = items

	scheduledEvents = []
	parentType = system.kanoa.utilities.getFieldValue('assetTypeName', system.kanoa.asset.getAssets({'assetPath':assetPath}))
	deviceUTCOffsetHrs = self.session.props.device.timezone.utcOffset

	for item in items:
		eventType = item['data']['eventType']
		assetId = item['data']['assetId']
		self.custom.info = {"showBar": True, "text": 'Getting %s info for %s'%(eventType, item['data']['eqPath']), "type": "INFO"}

		if eventType == 'Schedule':
			events = system.kanoa.schedule.getCalendarEvents({'scheduleType': 'operation', 'startDate': startDate, 'endDate': endDate, 'assetPath': item['data']['eqPath']})
			bgColorDict = buildColorDict(list(set([event['color'] for event in events])))
			for event in events: scheduledEvents.append(buildEvent(item['id'], event['startDate'], event['endDate'], buildLabel(event['modeName'], event['workOrderTitle'], event['itemName'], event['itemDescription']),  event['color']))
		elif eventType == 'Mode':
			events = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.event.getAssetProductionEvents({'assetId': assetId, 'startDate': startDate, 'endDate': endDate}))
			bgColorDict = buildColorDict(list(set([event['modeColor'] for event in events])))
			for event in events: scheduledEvents.append(buildEvent(item['id'], event['startDate'], event['endDate'], buildLabel(event['modeName'], event['workOrderTitle'], event['itemName'], event['itemDescription']),  event['modeColor']))
		elif eventType == 'State' and parentType not in ('ENTERPRISE'): #We can't afford to get all state date for all sites, just too much data			
			paramsDict = {'assetId': assetId, 'startDate': startDate, 'endDate': endDate, 'showDowntimeOnly': False, 'showChanged': None, 'durationSecs': 0}
			events = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.event.getAssetStateEvents(paramsDict))
			bgColorDict = buildColorDict(list(set([event['stateColor'] or event['stateTypeColor'] for event in events])))			
			for event in events: scheduledEvents.append(buildEvent(item['id'], event['startDate'], event['endDate'], event['stateName'],  event['stateColor'] or event['stateTypeColor']))
		else: continue

	self.view.custom.schedule = scheduledEvents

	self.custom.info = {"showBar": False, "text": "", "type": "INFO"}	

	return
